function icon(name, size = 16) {
  return `<svg class="ic" width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${ICONS[name] ?? ""}</svg>`;
}

// The Hermes mark: a winged stroke inside a tile, used as the agent avatar.
function hermesMark(size = 28) {
  return `<span class="agent-mark" style="width:${size}px;height:${size}px"><svg viewBox="0 0 24 24" width="${size * 0.6}" height="${size * 0.6}" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" aria-hidden="true"><path d="M5 18 12 6l7 12"/><path d="M8.5 12h7"/><path d="M3 9c2 0 3.5-1 4.5-3M21 9c-2 0-3.5-1-4.5-3"/></svg></span>`;
}
